<?php require 'app.php';[$w,$t,$a]=bb_owner();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{bb_check_csrf();$id=(int)($_POST['book_id'] ?? 0);if(!bb_one('SELECT book_id FROM books WHERE book_id=?','i',[$id])) throw new InvalidArgumentException('Book not found.');if(($_POST['action'] ?? '')==='remove') bb_query('DELETE FROM library WHERE '.$w.' AND book_id=?',$t.'i',array_merge($a,[$id]));elseif(($_POST['action'] ?? '')==='save'){if(bb_user_id()) bb_query('INSERT IGNORE INTO library(user_id,book_id) VALUES (?,?)','ii',[bb_user_id(),$id]);else bb_query('INSERT IGNORE INTO library(session_id,book_id) VALUES (?,?)','si',[session_id(),$id]);}else throw new InvalidArgumentException('Unknown action.');bb_redirect('library.php');}catch(InvalidArgumentException $e){$error=$e->getMessage();}}
$books=bb_rows('SELECT b.* FROM library l JOIN books b ON b.book_id=l.book_id WHERE l.'.$w.' ORDER BY l.added_at DESC',$t,$a);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Saved books | BookBang</title><link rel="stylesheet" href="backend.css"></head><body><?php include 'navbar.php'; ?><main class="bb-panel"><h1>Saved books</h1><?php if($error): ?><p class="bb-error"><?= bb_h($error) ?></p><?php endif; ?><?php if(!$books): ?><p>No saved books yet. Open a book and choose Save book.</p><?php endif; ?><?php foreach($books as $book): ?><div class="bb-item"><img src="<?= bb_h($book['image']) ?>" alt="<?= bb_h($book['title']) ?>"><a class="bb-title" href="ProductDescription.php?id=<?= (int)$book['book_id'] ?>"><?= bb_h($book['title']) ?></a><form method="post"><input type="hidden" name="csrf" value="<?= bb_h(bb_csrf()) ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="book_id" value="<?= (int)$book['book_id'] ?>"><button>Remove</button></form></div><?php endforeach; ?></main></body></html>
